def main():
    check = "--check" in sys.argv
    base = os.path.dirname(__file__) or "."
    seen = set()
    for path in sorted(glob.glob(os.path.join(base, "*.json"))):
        if os.path.basename(path) == "cross_subject_edges.json":
            continue
        d = json.load(open(path, encoding="utf-8"))
        if "nodes" not in d:
            continue
        n_changed = 0
        for n in d["nodes"]:
            if n.get("kind") == "concept" and n["id"] in DESC:
                seen.add(n["id"])
                if n.get("description") != DESC[n["id"]]:
                    n["description"] = DESC[n["id"]]
                    n_changed += 1
        if n_changed and not check:
            json.dump(d, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
        if n_changed:
            print(f"{os.path.basename(path):38} {n_changed} descriptions set")
    missing = set(DESC) - seen
    if missing:
        print("WARNING: ids in DESC not found in any graph:", sorted(missing))

if __name__ == "__main__":
    main()
